-- Run once on an existing VideoHub24162049 database.
USE VideoHub24162049;
GO
IF COL_LENGTH('Videos','Price') IS NULL ALTER TABLE Videos ADD Price DECIMAL(18,2) NOT NULL CONSTRAINT DF_Videos_Price DEFAULT 99000;
IF COL_LENGTH('Videos','Stock') IS NULL ALTER TABLE Videos ADD Stock INT NOT NULL CONSTRAINT DF_Videos_Stock DEFAULT 25;
GO
UPDATE Videos SET Price=CASE CategoryId WHEN 1 THEN 149000 WHEN 2 THEN 199000 WHEN 3 THEN 119000 ELSE 99000 END+(CAST(RIGHT(VideoId,3) AS INT)%4)*10000,Stock=10+(CAST(RIGHT(VideoId,3) AS INT)%6)*5 WHERE Price=99000 AND Stock=25;
GO
IF OBJECT_ID('Orders','U') IS NULL CREATE TABLE Orders(
 OrderId BIGINT IDENTITY(1,1) PRIMARY KEY,Username NVARCHAR(50) NOT NULL REFERENCES Users(Username),RecipientName NVARCHAR(100) NOT NULL,Phone NVARCHAR(15) NOT NULL,Address NVARCHAR(300) NOT NULL,Note NVARCHAR(500) NULL,PaymentMethod VARCHAR(10) NOT NULL DEFAULT 'COD' CHECK(PaymentMethod='COD'),Status VARCHAR(20) NOT NULL DEFAULT 'NEW' CHECK(Status IN ('NEW','CONFIRMED','PREPARING','SHIPPING','DELIVERING','DELIVERED','CANCELLED','RETURNED')),TotalAmount DECIMAL(18,2) NOT NULL CHECK(TotalAmount>=0),CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('OrderItems','U') IS NULL CREATE TABLE OrderItems(
 OrderItemId BIGINT IDENTITY(1,1) PRIMARY KEY,OrderId BIGINT NOT NULL REFERENCES Orders(OrderId),VideoId NVARCHAR(50) NOT NULL REFERENCES Videos(VideoId),Title NVARCHAR(200) NOT NULL,Poster NVARCHAR(500) NOT NULL,UnitPrice DECIMAL(18,2) NOT NULL CHECK(UnitPrice>=0),Quantity INT NOT NULL CHECK(Quantity BETWEEN 1 AND 20));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Orders_User_Status_Date') CREATE INDEX IX_Orders_User_Status_Date ON Orders(Username,Status,CreatedAt DESC);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_OrderItems_Order') CREATE INDEX IX_OrderItems_Order ON OrderItems(OrderId);
GO
